import{_ as e,o,c as r,ag as n}from"./chunks/framework.2cFhd8Ux.js";const p=JSON.parse('{"title":"The Final Presentation","description":"","frontmatter":{"source":"project/final-presentation.md"},"headers":[],"relativePath":"project/final-presentation.md","filePath":"project/final-presentation.md"}'),a={name:"project/final-presentation.md"};function s(i,t,d,h,l,c){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="the-final-presentation" tabindex="-1">The Final Presentation <a class="header-anchor" href="#the-final-presentation" aria-label="Permalink to &quot;The Final Presentation&quot;">​</a></h1><blockquote><p>The course&#39;s final event, in finals week. There is no final examination. Each team presents its contribution with a live demo: behavior you can show, a check anyone can rerun, and a limitation you name yourself.</p></blockquote><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>When</strong></td><td>Finals week (week 16), in the course&#39;s scheduled final exam period (Regulation H-1-b): [day, time and room, posted on Canvas]</td></tr><tr><td><strong>Format</strong></td><td>Ten minutes per team: a presentation of your contribution with a live demo, then a minute or two of questions from the room</td></tr><tr><td><strong>Points</strong></td><td>10 of the Final&#39;s 45, Team (<a href="#rubric">rubric</a>). The other 35 are the <a href="./../assessment/rubrics.html#final-report-and-repository">report and repository</a></td></tr><tr><td><strong>Due at the start of the period</strong></td><td>The team&#39;s work in the class fork (staff tag <code>main</code> as <code>final</code>), the final report and each member&#39;s peer evaluation 3 on Canvas, and the CS [5xxx] study paper (<a href="./milestones.html#final">milestones</a>)</td></tr></tbody></table><h2 id="the-principle" tabindex="-1">The principle <a class="header-anchor" href="#the-principle" aria-label="Permalink to &quot;The principle&quot;">​</a></h2><p>The presentation, like the final report, is graded on the rule UT Austin&#39;s CS 378 sets for its final projects:</p><blockquote><p>&quot;Feature count, repository size, token spend, prompt volume, and visual polish do not substitute for demonstrated behavior, reproducible checks, controlled engineering decisions, or honest limitations.&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">UT Austin CS 378</a>)</p></blockquote><p>A small contribution that works, with a check you rerun in front of the room and a limitation you name before anyone asks, scores better than a large one you can&#39;t verify.</p><h2 id="what-to-present" tabindex="-1">What to present <a class="header-anchor" href="#what-to-present" aria-label="Permalink to &quot;What to present&quot;">​</a></h2><ol><li><strong>What you contributed and why</strong>, in one sentence each.</li><li><strong>The contribution working</strong> in the class codebase, on the <code>final</code> tag: the main scenario from your spec and one edge case.</li><li><strong>One check rerun live:</strong> your test suite, a mutation run or your eval on recorded responses, compared with the number in your report. If it takes more than a minute or two, start it first and show the result at the end.</li><li><strong>One honest limitation,</strong> stated without being asked.</li></ol><p>Any member may present; nobody has to speak if that is a barrier. Prepare a fallback for each step (a CI run on the tagged commit, screenshots), and open a Codespace on the tag 30 minutes early. Rehearse in the week 15 Lab.</p><h2 id="rubric" tabindex="-1">Rubric <a class="header-anchor" href="#rubric" aria-label="Permalink to &quot;Rubric&quot;">​</a></h2><p><strong>10 points, Team.</strong></p><table tabindex="0"><thead><tr><th>Criterion</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Demonstrated behavior</strong></td><td><strong>4</strong> · The contribution works live on the <code>final</code> tag, on the main scenario and an edge case, as the report says</td><td><strong>3</strong> · Works on the main scenario; the edge case is shown from a test</td><td><strong>1</strong> · Works only partly, or only from screenshots without a reason</td><td><strong>0</strong> · Not shown</td></tr><tr><td><strong>Reproducible check</strong></td><td><strong>3</strong> · A check rerun live (or its CI run on the tagged commit opened live), and its result matches the report</td><td><strong>2</strong> · Rerun, with a small unexplained difference from the report</td><td><strong>1</strong> · Only described, not run</td><td><strong>0</strong> · None</td></tr><tr><td><strong>Honest limitations</strong></td><td><strong>3</strong> · At least one real limitation stated without being asked, with what it means for a user or maintainer</td><td><strong>2</strong> · A limitation stated when asked</td><td><strong>1</strong> · &quot;No limitations&quot;</td><td><strong>0</strong> · Claims contradicted by the demo itself</td></tr></tbody></table><h2 id="if-you-miss-it" tabindex="-1">If you miss it <a class="header-anchor" href="#if-you-miss-it" aria-label="Permalink to &quot;If you miss it&quot;">​</a></h2><p>The team presents without you, and its score is unchanged. Tell the instructor as soon as you can; your peer evaluation 3 and the team&#39;s deliverables are still due at the start of the period.</p>',15)])])}const m=e(a,[["render",s]]);export{p as __pageData,m as default};
